#include "low_basis.hpp"
int main(int argc,char**argv){if(argc<3)return 2;ifstream f(argv[1]);QBasis b;PolyWord p;string header;int i=0;auto start=chrono::steady_clock::now();while(getline(f,header)){if(header.empty())continue;istringstream s(header);U context;s>>context;int nr;f>>nr;QP row;for(int j=0;j<nr;j++){W w;string cs;f>>w>>cs;mpq_class c(cs);c.canonicalize();for(auto[m,d]:p.get(w))qadd(row,m,c*d);}string dummy;getline(f,dummy);QP full;qmuladd(full,row,context,1,true);b.labels.push_back(header);b.insert(move(full),i++);if(i%500==0)cerr<<"LOW row="<<i<<" rank="<<b.basis.size()<<" sec="<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<"\n";}b.save(argv[2]);cerr<<"BUILT rows="<<i<<" rank="<<b.basis.size()<<" columns="<<(b.leads.size())<<"\n";}
